//! Explicit luminance-ray exponential shoulder, not an ACES output transform.
use crate::effects::{Frame,Params,p};
pub fn map(y:f64,knee:f64,peak:f64)->f64{if y<=knee{y}else{knee+(peak-knee)*(1.-(-(y-knee)/(peak-knee)).exp())}}
pub fn apply(pr:&Params,f:&mut Frame,t:f64)->Result<(),String>{super::frame::validate(f)?;let g=p(pr,"gamut",0.,t) as f64;let knee=p(pr,"knee",0.75,t) as f64;let peak=p(pr,"peak",1.,t) as f64;let amount=p(pr,"amount",1.,t) as f64;if g.fract()!=0.||!(0. ..=7.).contains(&g)||!knee.is_finite()||!peak.is_finite()||knee<0.||peak<=knee||peak>1000.||!(0. ..=1.).contains(&amount){return Err("invalid luminance shoulder params".into())}let weights=super::managed::luma_weights(g as usize);for(i,px) in f.d.chunks_exact_mut(4).enumerate(){if i%65536==0{crate::guard::check()}if px[..3].iter().any(|v|!v.is_finite()){return Err("nonfinite shoulder input".into())}let y=(0..3).map(|j|weights[j]*px[j] as f64).sum::<f64>();if y>knee{let ratio=1.+amount*(map(y,knee,peak)/y-1.);for j in 0..3{let v=px[j] as f64*ratio;if !v.is_finite()||v.abs()>f32::MAX as f64{return Err("shoulder overflow".into())}px[j]=v as f32;}}}Ok(())}
pub fn catalog()->Vec<super::Entry>{vec![("luminance_shoulder","Explicit linear RGB exponential shoulder on a gamut-luminance ray: identity below knee, smooth bounded luminance above. RGB ratios preserved, NOT perceptual hue guarantee or gamut mapping. Negative luma untouched. No encoding, ACES RRT/ODT or display certification.",&[("gamut",0.,"linear gamut0..7"),("knee",0.75,"linear luminance>=0"),("peak",1.,"asymptotic luminance>knee up to1000"),("amount",1.,"0..1")])]}
